#!/bin/sh
# Run in the locked build image; /out must be new. Input is an inspected .deb-derived plan.
# This collects candidates, not proof that the installer is cleared.
set -eu
export LC_ALL=C
test -d /out
test -z "$(ls -A /out)" || { echo 'output directory must be empty' >&2; exit 1; }
test "$(id -u)" = 0
test "$#" -eq 1 || { echo 'usage: collect-debian-sources.sh /in/source-plan.json.tsv' >&2; exit 1; }
plan=$1
test -f "$plan"
# The plan is generated by release-materials.js from hash-verified binary packages.
# No executable expressions or arbitrary path names are accepted.
head -n 1 "$plan" | LC_ALL=C grep -Eq '^# amdl-debian-source-plan-v1 installer=[a-f0-9]{64} manifest=[a-f0-9]{64} snapshot=20260728T000000Z$'
awk -F '\t' 'NR==1 {next} NF!=2 || $1 !~ /^[a-z0-9][a-z0-9+.-]*$/ || $2 !~ /^[0-9][0-9A-Za-z.+:~\-]*$/ {exit 1} {if(seen[$1]++) exit 1; n++} END {if(!n) exit 1}' "$plan"
mkdir -p /out/apt/lists/partial /out/apt/cache/archives/partial
cp "$plan" /out/SOURCE-PLAN.tsv
printf '%s\n' \
  'deb-src https://snapshot.debian.org/archive/debian/20260728T000000Z/ bookworm main' \
  'deb-src https://snapshot.debian.org/archive/debian-security/20260728T000000Z/ bookworm-security main' > /out/sources.list
aptget() {
  apt-get -o Acquire::Check-Valid-Until=false \
    -o Dir::Etc::sourcelist=/out/sources.list -o Dir::Etc::sourceparts=- \
    -o Dir::State::lists=/out/apt/lists -o Dir::Cache=/out/apt/cache "$@"
}
aptget update
# For 1.0.1 the plan includes linux=6.1.177-1, linux-signed-amd64=6.1.177+1,
# busybox=1:1.35.0-4+deb12u1 and glibc=2.36-9+deb12u14.
tab=$(printf '\t')
tail -n +2 "$plan" | while IFS="$tab" read -r package version; do
  mkdir "/out/$package"
  (cd "/out/$package" && aptget source --download-only "$package=$version")
done
# Validate source archive checksums without unpacking the large kernel tree.
# APT verifies snapshot indexes; .dsc signature verification is separate.
tail -n +2 "$plan" | while IFS="$tab" read -r package version; do
  cd "/out/$package"
  set -- ./*.dsc
  test "$#" -eq 1 && test -f "$1"
  awk '/^Checksums-Sha256:/{inside=1;next} inside && /^[^ ]/{exit} inside && /^ / {
    if (length($1)!=64 || $1 !~ /^[0-9a-f]+$/ || $3 ~ /\// || $3 ~ /^\./) exit 1;
    print $1 "  " $3; count++
  } END {if (!count) exit 1}' "$1" > SHA256SUMS.source
  sha256sum -c SHA256SUMS.source
  find . -maxdepth 1 -type f ! -name SHA256SUMS -print0 | sort -z | xargs -0 sha256sum > SHA256SUMS
  cd /out
done
printf '%s\n' 'Snapshot: 20260728T000000Z' 'Source identities: SOURCE-PLAN.tsv' \
  'APT indexes retained under apt/lists; .dsc signatures not independently verified.' \
  'Source candidates only. Rebuild, static-linking material and authorization review remain incomplete.' > /out/SOURCE-IDENTITY.txt
echo 'Debian source candidates collected; review and delivery remain required.'
